from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund, SUPPORT_APPROVAL_THRESHOLD
from ledgerly.models import Payment
from ledgerly.errors import BillingError

T0 = datetime(2026,10,1,tzinfo=timezone.utc)
def p(amt="2000.00", status="captured", refunded="0.00"):
    return Payment("pay","inv",Decimal(amt),status=status,created_at=T0,captured_at=T0,refunded_amount=Decimal(refunded))

print("threshold", SUPPORT_APPROVAL_THRESHOLD)
# at threshold no approval
x=p(); outage_refund(x, Decimal("1000.00"), T0); print("at threshold ok", x.refunded_amount)
# above threshold requires approval
try: outage_refund(p(), Decimal("1000.01"), T0)
except BillingError as e: print("above no approval:", e.code)
# above with approval
x=p(); outage_refund(x, Decimal("1000.01"), T0, approved_by="mgr"); print("approved ok", x.refunded_amount)
# full refund sets status
x=p("80.00"); outage_refund(x, Decimal("80.00"), T0); print("full:", x.status, x.refunded_amount)
# over refund
try: outage_refund(p("80.00"), Decimal("80.01"), T0)
except BillingError as e: print("over:", e.code)
# non captured
try: outage_refund(p(status="authorized"), Decimal("1.00"), T0)
except BillingError as e: print("state:", e.code)
# non positive
try: outage_refund(p(), Decimal("0"), T0)
except BillingError as e: print("nonpos:", e.code)
EOF"}

